const dashboardMessages = Object.fromEntries(['en', 'hi', 'kn'].map((language) => [language, {
  copy: copy[language], medicationCopy: medicationCopy[language], activityCopy: activityCopy[language], contactCopy: contactCopy[language], extraPageCopy: extraPageCopy[language], dashboardNavigation: dashboardNavigation[language],
}]))

function dashboardForLanguage(language) {
  const selected = dashboardMessages[language] ?? dashboardMessages.en
  const sections = ['copy', 'medicationCopy', 'activityCopy', 'contactCopy', 'extraPageCopy', 'dashboardNavigation']
  return Object.fromEntries(sections.map((section) => [section, {
    ...dashboardMessages.en[section],
    ...(selected[section] ?? {}),
  }]))
}

const LanguageContext = createContext(null)

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    try {
      const saved = window.localStorage.getItem('eldercare-language')
      return languageOptions.some(({ id }) => id === saved) ? saved : 'en'
    } catch { return 'en' }
  })

  useEffect(() => {
    try { window.localStorage.setItem('eldercare-language', language) } catch { /* Storage may be unavailable. */ }
    document.documentElement.lang = language
  }, [language])

  const value = useMemo(() => ({
    language,
    setLanguage,
    options: languageOptions,
    dashboard: dashboardMessages[language],
    dashboardForLanguage,
    t: (key) => messages[language][key] ?? shareMessages[language][key] ?? messages.en[key] ?? shareMessages.en[key] ?? key,
  }), [language])

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>
}

export function useLanguage() {
  const value = useContext(LanguageContext)
  if (!value) throw new Error('useLanguage must be used inside LanguageProvider.')
  return value
}

export function LanguageSelector({ className = '' }) {
  const { language, setLanguage, options, t } = useLanguage()
  return (
    <label className={`language-select ${className}`}>
      <span>{t('language')}</span>
      <select value={language} onChange={(event) => setLanguage(event.target.value)} aria-label={t('language')}>
        {options.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}
      </select>
    </label>
  )
}
